import { DataSource } from 'typeorm';

import { afterAll, beforeAll, describe, expect, it } from 'vitest';

import { User } from '../../modules/users/entities/index.js';
import { buildFromSource } from './build-criteria.js';
import {
  applyCursorBoundary,
  applyFilters,
  applySort,
} from './apply-criteria.js';
import { readPage } from './read-page.js';
import type { QuerySpec } from './query-spec.js';

/**
 * The SQL these tests assert on is **generated by TypeORM itself**, from a real
 * entity and a real metadata graph.
 *
 * A test that asserts on the fragments this application assembled proves only
 * that the fragments are what the test expected. What matters is the statement
 * postgres will receive: the column names escaped, the values bound, the
 * qualifiers right. A `DataSource` built without connecting is enough for that,
 * because `getQueryAndParameters` is pure — it renders the SQL and the
 * parameters and never opens a socket.
 */
describe('the SQL a criteria produces', () => {
  let dataSource: DataSource;

  const SPEC = {
    filters: {
      role: { column: 'role', operator: 'eq' },
      isActive: { column: 'isActive', operator: 'eq' },
      email: { column: 'email', operator: 'ilike' },
      tags: { column: 'tags', operator: 'in', list: true },
    },
    sort: {
      createdAt: 'createdAt',
      email: 'email',
    },
    defaultSort: 'createdAt',
  } as const satisfies QuerySpec;

  beforeAll(async () => {
    dataSource = new DataSource({
      type: 'postgres',
      entities: [User],
    });

    // The metadata is built by hand rather than by `initialize()`, which would
    // open a connection. `buildMetadatas` is what `initialize` calls before it
    // connects, and it is all that is needed to render a query.
    await (
      dataSource as unknown as { buildMetadatas(): Promise<void> }
    ).buildMetadatas();
  });

  afterAll(async () => {
    if (dataSource.isInitialized) {
      await dataSource.destroy();
    }
  });

  function query() {
    return dataSource.getRepository(User).createQueryBuilder('user');
  }

  it('binds every filter value as a parameter', () => {
    const criteria = buildFromSource({ filters: { role: 'admin' } }, SPEC);
    const qb = query();

    applyFilters(qb, criteria, 'user');

    const [sql, parameters] = qb.getQueryAndParameters();

    // The value is nowhere in the statement. A value that reached the SQL text
    // would be a value that could change what the statement means.
    expect(sql).not.toContain('admin');
    expect(parameters).toContain('admin');
  });

  it('escapes the column and qualifies it with the alias', () => {
    const criteria = buildFromSource({ filters: { role: 'admin' } }, SPEC);
    const qb = query();

    applyFilters(qb, criteria, 'user');

    const [sql] = qb.getQueryAndParameters();

    expect(sql).toContain('"user"."role"');
  });

  it('escapes the wildcards in a search term', () => {
    const criteria = buildFromSource({ filters: { email: 'a_%b' } }, SPEC);
    const qb = query();

    applyFilters(qb, criteria, 'user');

    const [sql, parameters] = qb.getQueryAndParameters();

    // The `%` and `_` are the user's, and they are matched literally. A search
    // box that treats them as wildcards returns rows nobody asked for.
    expect(sql).toContain('ILIKE');
    expect(parameters).toContain('%a\\_\\%b%');
  });

  it('declares the escape character, so the term does not depend on the server', () => {
    const criteria = buildFromSource({ filters: { email: 'a' } }, SPEC);
    const qb = query();

    applyFilters(qb, criteria, 'user');

    const [sql] = qb.getQueryAndParameters();

    // Postgres defaults `LIKE`'s escape to a backslash, but stating it means the
    // behaviour does not depend on the server's configuration.
    expect(sql).toContain("ESCAPE '\\'");

    // And the statement would not be valid without it: an unescaped `\\` in the
    // bound value would be a wildcard, so the term would match rows the client
    // did not ask for.
    expect(sql).not.toMatch(/ILIKE :filter_0$/);
  });

  it('expands a list into one placeholder per element', () => {
    const criteria = buildFromSource({ filters: { tags: ['a', 'b'] } }, SPEC);
    const qb = query();

    applyFilters(qb, criteria, 'user');

    const [sql, parameters] = qb.getQueryAndParameters();

    // Not one string of two ids, which postgres could not use an index for.
    expect(sql).toContain('IN ($1, $2)');
    expect(parameters).toEqual(['a', 'b']);
  });

  it('qualifies the sort and the tie-break with the alias', () => {
    const criteria = buildFromSource({ sort: 'email' }, SPEC);
    const qb = query();

    applySort(qb, criteria, 'user');

    const [sql] = qb.getQueryAndParameters();

    // Qualified, because an unqualified column is ambiguous the moment the
    // query joins a second table — which is exactly what a future route on this
    // entity will do.
    expect(sql).toContain('ORDER BY "user"."email" DESC, "user"."id" DESC');
  });

  it('binds the cursor boundary as two parameters', () => {
    const criteria = buildFromSource(
      {
        cursor:
          'eyJ2IjoxLCJzIjoiMjAyNi0wOS0wM1QwMzoxNzowMC4wMDBaIiwiaSI6InUxIn0',
      },
      SPEC,
    );
    const qb = query();

    applyCursorBoundary(qb, criteria, 'user');

    const [sql, parameters] = qb.getQueryAndParameters();

    expect(sql).toContain('"user"."createdAt" < $1');
    expect(sql).toContain('"user"."id" < $2');
    expect(parameters).toEqual(['2026-09-03T03:17:00.000Z', 'u1']);
  });

  it('reads a page with the filters, the boundary and the sort in one statement', async () => {
    const criteria = buildFromSource(
      { filters: { role: 'admin' }, limit: 2, sort: 'email' },
      SPEC,
    );
    const qb = query();

    // The builder's `getMany` needs a connection, so the page is read against
    // a builder whose `getMany` is replaced with the rows the criteria says
    // should come back. What is asserted here is the statement, not the rows.
    const captured: { sql?: string; parameters?: unknown[] } = {};

    qb.getMany = async () => {
      const [sql, parameters] = qb.getQueryAndParameters();

      captured.sql = sql;
      captured.parameters = parameters;

      return [];
    };

    const page = await readPage({ query: qb, criteria, alias: 'user' });

    expect(captured.sql).toContain('"user"."role" = $1');
    expect(captured.sql).toContain('ORDER BY "user"."email" DESC');
    expect(captured.sql).toContain('LIMIT 3');
    expect(captured.parameters).toContain('admin');
    expect(page.items).toEqual([]);
    expect(page.meta).toEqual({ limit: 2, hasMore: false, nextCursor: null });
  });
});
